from html.parser import HTMLParser
from pathlib import Path
p=Path("${TMPDIR%/}/ambah_verify_94454/search_0.html")
class P(HTMLParser):
    def __init__(self): super().__init__(); self.in_result=False; self.in_h2=False; self.in_p=False; self.href=None; self.buf=[]; self.rows=[]
    def handle_starttag(self,tag,attrs):
        a=dict(attrs)
        if tag=='"'li' and 'b_algo' in a.get('class',''):
            self.in_result=True; self.href=None; self.buf=[]
        elif self.in_result and tag=='h2': self.in_h2=True; self.buf=[]
        elif self.in_result and tag=='a' and self.href is None: self.href=a.get('href')
        elif self.in_result and tag=='p': self.in_p=True; self.buf=[]
    def handle_data(self,d):
        if self.in_h2 or self.in_p: self.buf.append(d)
    def handle_endtag(self,tag):
        if tag=='h2' and self.in_h2:
            title=' '.join(''.join(self.buf).split()); self.in_h2=False; self.buf=[]
            self.rows.append([title,self.href,''])
        elif tag=='p' and self.in_p:
            snip=' '.join(''.join(self.buf).split()); self.in_p=False; self.buf=[]
            if self.rows: self.rows[-1][2]=snip
        elif tag=='li' and self.in_result:
            self.in_result=False
parser=P(); parser.feed(p.read_text(errors='ignore'))
for row in parser.rows:
    print('TITLE:',row[0]); print('URL:',row[1]); print('SNIP:',row[2]); print()
